  "not_available": [
    {
      "technique": "Powder X-ray Diffraction (PXRD)",
      "why_useful": "PXRD is the standard, non-destructive technique for identifying and quantifying bulk crystalline phases in powders by matching diffraction patterns against crystallographic databases."
