    {
      "instrument_id": "EQ17",
      "role": "supplementary",
      "technique": "Thermogravimetric analysis (TGA)",
      "why": "Measures thermal decomposition onset to verify that the polymer is thermally stable at 280 °C and will not degrade during the rheological test.",
